// Helper for this exercise only.
// The printed listing uses HashSet but imports only java.util.Set, so this
// small stand-in (a plain java.util.HashSet under another name) lets the
// code compile and run exactly as it appears in the book. In your own
// programs, just write: import java.util.HashSet;
public class HashSet<E> extends java.util.HashSet<E> {
    public HashSet() {
        super();
    }

    public HashSet(java.util.Collection<? extends E> source) {
        super(source);
    }
}
